def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return min(budget, DAILY_SALARY * 0.9)
        return min(budget, DAILY_SALARY * 0.25)

    prev_bids = []
    threat_scores = []
    desperate_count = 0
    rich_count = 0

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        pbid = None
        if prev and prev.get('bid') is not None:
            pbid = prev.get('bid')
            prev_bids.append(pbid)
        else:
            pbid = DAILY_SALARY * 0.8

        obudget = opp.get('budget', 0)
        ohp = opp.get('hp', 10)
        onwd = opp.get('no_water_days', 0)
        oreq = opp.get('water_requirement', WATER_REQ)
        osalary = opp.get('daily_salary', DAILY_SALARY)

        if obudget < DAILY_SALARY * 2 and (ohp <= 3 or onwd >= 1):
            desperate_count += 1
        if obudget > 500:
            rich_count += 1

        score = pbid
        if ohp <= 3 or onwd >= 1:
            score += 10
        if obudget < pbid:
            score -= 8
        if oreq > WATER_REQ:
            score += 3
        if osalary > DAILY_SALARY:
            score += 2
        threat_scores.append(score)

    highest_prev = max(prev_bids) if prev_bids else DAILY_SALARY * 0.9
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else DAILY_SALARY * 0.8
    max_threat = max(threat_scores) if threat_scores else highest_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0
    if scarcity > 1:
        scarcity = 1

    urgency = 0.0
    if hp <= 2:
        urgency += 0.7
    elif hp <= 4:
        urgency += 0.35
    if no_water_days >= 2:
        urgency += 0.7
    elif no_water_days == 1:
        urgency += 0.3

    base = avg_prev * 0.78 + max_threat * 0.22
    base += scarcity * 14

    if day <= 2 and hp >= 8:
        base -= 8

    if desperate_count >= 2 and hp >= 5:
        base -= 10

    if rich_count >= 2:
        base += 6

    if urgency >= 0.7:
        bid = max(base + 10, highest_prev + 2.5)
    elif urgency >= 0.3:
        bid = max(base + 3, avg_prev + 1.5)
    else:
        bid = base - 6

    if supply >= 23 and hp >= 6 and no_water_days == 0:
        bid -= 10
    elif supply <= 17:
        bid += 8

    reserve = 0
    if day < 10:
        reserve = max(0, (10 - day) * 6)

    max_affordable = max(0, budget - reserve)
    if hp <= 2 or no_water_days >= 2:
        max_affordable = budget

    if max_affordable <= 0:
        return min(budget, DAILY_SALARY * 0.15)

    floor_bid = DAILY_SALARY * 0.18
    if hp <= 3 or no_water_days >= 1:
        floor_bid = DAILY_SALARY * 0.45

    bid = max(floor_bid, bid)
    bid = min(bid, max_affordable)
    bid = min(bid, budget)

    if bid < 0:
        bid = 0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return int(min(my_status.get('budget', 0), DAILY_SALARY * 0.4))

    # Use only yesterday previous_trace for immediate reaction
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))

    if hp <= 2:
        # Desperation: ensure we get water
        target = DAILY_SALARY * 0.95
    else:
        # Base bid depends on supply: higher supply => can bid less
        # supply in [15,25] => map to [0.65,0.45] of salary
        if MAX_SUPPLY > MIN_SUPPLY:
            t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        else:
            t = 0.5
        t = max(0.0, min(1.0, float(t)))
        base = DAILY_SALARY * (0.65 - 0.20 * t)

        if yesterday_bids:
            max_prev = max(yesterday_bids)
            # If opponents were bidding very high yesterday, slightly outbid to survive
            if max_prev >= DAILY_SALARY * 0.85:
                target = max(base, max_prev * 0.90)
            else:
                # Otherwise bid to beat typical pressure without draining budget
                # Aim around median-ish by nudging toward max but not exceeding it
                sorted_b = sorted(yesterday_bids)
                mid = sorted_b[len(sorted_b)//2] if len(sorted_b) > 0 else max_prev
                target = max(base, min(max_prev, mid + 5.0))
        else:
            target = base

    # Avoid catastrophic spending: keep a reserve for later days
    # If budget is low, cap at a fraction of budget.
    if budget <= 0:
        return 0

    reserve_fraction = 0.35
    cap = budget * (1.0 - reserve_fraction)
    target = min(target, cap)

    # Also ensure non-negative integer bid
    bid = int(max(0, min(budget, target)))
    return bid

def get_bid(day_context, my_status, opponents_status):
