    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    high_competition_threshold = DAILY_SALARY * 0.85
    desperate_bid = DAILY_SALARY * 0.95
    moderate_bid_floor = DAILY_SALARY * 0.5
    conservative_bid_hp_high = DAILY_SALARY * 0.3
    fallback_desperate_bid = DAILY_SALARY * 0.9
    fallback_moderate_bid = DAILY_SALARY * 0.55

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= high_competition_threshold:
            if my_status['hp'] > 3:
                return min(my_status['budget'], conservative_bid_hp_high)
            else:
                return min(my_status['budget'], desperate_bid)
        else:
            return min(my_status['budget'], max(moderate_bid_floor, highest_prev_bid + 1.5))
    else:
        if my_status['hp'] <= 2:
            return min(my_status['budget'], fallback_desperate_bid)
        else:
            return min(my_status['budget'], fallback_moderate_bid)
